-- Whole39-task progression/reward dependency. Remains disabled until complete world/journal activation.
-- Faction is configured on the native task row; it is not a fake reward-selection wire type.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbs_reward_sets`;
CREATE TEMPORARY TABLE `_tbs_reward_sets` LIKE `reward_sets`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_reward_sources`;
CREATE TEMPORARY TABLE `_tbs_reward_sources` LIKE `reward_sources`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_reward_options`;
CREATE TEMPORARY TABLE `_tbs_reward_options` LIKE `reward_options`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_rewards`;
CREATE TEMPORARY TABLE `_tbs_rewards` LIKE `rewards`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_reward_option_entries`;
CREATE TEMPORARY TABLE `_tbs_reward_option_entries` LIKE `reward_option_entries`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_task_reward_progression_members`;
CREATE TEMPORARY TABLE `_tbs_task_reward_progression_members` LIKE `task_reward_progression_members`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_task_reward_option_gates`;
CREATE TEMPORARY TABLE `_tbs_task_reward_option_gates` LIKE `task_reward_option_gates`;
DROP TEMPORARY TABLE IF EXISTS `_tbs_rewards_guard`;
CREATE TEMPORARY TABLE `_tbs_rewards_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
SET @tbs_rewards_ok=
(COALESCE(@buriedsea_whole_batch_reviewed,0)=1)
 AND ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN(CONVERT(0x7265776172645f73657473 USING utf8mb4),CONVERT(0x7265776172645f736f7572636573 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e73 USING utf8mb4),CONVERT(0x72657761726473 USING utf8mb4),CONVERT(0x7265776172645f6f7074696f6e5f656e7472696573 USING utf8mb4),CONVERT(0x7461736b5f7265776172645f70726f6772657373696f6e5f6d656d62657273 USING utf8mb4),CONVERT(0x7461736b5f7265776172645f6f7074696f6e5f6761746573 USING utf8mb4)) AND ENGINE='InnoDB')=7)
 AND (NOT EXISTS(SELECT 1 FROM `reward_sets` a WHERE (a.reward_set_id BETWEEN 3040901 AND 3040939) AND NOT EXISTS(SELECT 1 FROM `_tbs_reward_sets` e WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`title`<=>e.`title` AND a.enabled IN(0,1))))
 AND (NOT EXISTS(SELECT 1 FROM `reward_sources` a WHERE (a.source_type=2 AND a.source_id BETWEEN 3040901 AND 3040939) AND NOT EXISTS(SELECT 1 FROM `_tbs_reward_sources` e WHERE a.`source_type`<=>e.`source_type` AND a.`source_id`<=>e.`source_id` AND a.`reward_set_id`<=>e.`reward_set_id` AND a.enabled IN(0,1))))
 AND (NOT EXISTS(SELECT 1 FROM `reward_options` a WHERE (a.reward_set_id BETWEEN 3040901 AND 3040939) AND NOT EXISTS(SELECT 1 FROM `_tbs_reward_options` e WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id` AND a.`sequence`<=>e.`sequence` AND a.`label`<=>e.`label` AND a.`common_to_all`<=>e.`common_to_all` AND a.`flags`<=>e.`flags` AND a.`class_mask`<=>e.`class_mask` AND a.enabled IN(0,1))))
