INSERT INTO `_tbs_rewards_guard`VALUES(COALESCE(@tbs_rewards_ok,0));
INSERT INTO `reward_sets`(`reward_set_id`,`title`,`enabled`)SELECT e.`reward_set_id`,e.`title`,e.`enabled` FROM `_tbs_reward_sets` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sets` a WHERE a.`reward_set_id`<=>e.`reward_set_id`);
INSERT INTO `reward_sources`(`source_type`,`source_id`,`reward_set_id`,`enabled`)SELECT e.`source_type`,e.`source_id`,e.`reward_set_id`,e.`enabled` FROM `_tbs_reward_sources` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_sources` a WHERE a.`source_type`<=>e.`source_type` AND a.`source_id`<=>e.`source_id`);
INSERT INTO `reward_options`(`reward_set_id`,`option_id`,`sequence`,`label`,`common_to_all`,`flags`,`enabled`,`class_mask`)SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`label`,e.`common_to_all`,e.`flags`,e.`enabled`,e.`class_mask` FROM `_tbs_reward_options` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_options` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id`);
INSERT INTO `rewards`(`reward_id`,`reward_type`,`reward_data_id`,`amount`,`description`,`enabled`)SELECT e.`reward_id`,e.`reward_type`,e.`reward_data_id`,e.`amount`,e.`description`,e.`enabled` FROM `_tbs_rewards` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `rewards` a WHERE a.`reward_id`<=>e.`reward_id`);
INSERT INTO `reward_option_entries`(`reward_set_id`,`option_id`,`sequence`,`reward_id`)SELECT e.`reward_set_id`,e.`option_id`,e.`sequence`,e.`reward_id` FROM `_tbs_reward_option_entries` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `reward_option_entries` a WHERE a.`reward_set_id`<=>e.`reward_set_id` AND a.`option_id`<=>e.`option_id` AND a.`sequence`<=>e.`sequence`);
INSERT INTO `task_reward_progression_members`(`task_id`,`qualifying_task_id`)SELECT e.`task_id`,e.`qualifying_task_id` FROM `_tbs_task_reward_progression_members` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `task_reward_progression_members` a WHERE a.`task_id`<=>e.`task_id` AND a.`qualifying_task_id`<=>e.`qualifying_task_id`);
INSERT INTO `task_reward_option_gates`(`task_id`,`option_id`,`minimum_completions`)SELECT e.`task_id`,e.`option_id`,e.`minimum_completions` FROM `_tbs_task_reward_option_gates` e WHERE @tbs_rewards_ok=1 AND NOT EXISTS(SELECT 1 FROM `task_reward_option_gates` a WHERE a.`task_id`<=>e.`task_id` AND a.`option_id`<=>e.`option_id`);
